<script module lang="ts">
/**
 * Links to a page's sections, the current marked (`design/components/table-of-contents.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/table-of-contents.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import {
  agentMember,
  agentPress,
  joinSlot,
  jumpToSection,
  watchEffect,
  watchSections,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/table-of-contents.module.css'

export interface TableOfContentsItem {
  id: string
  label: string
  level?: 1 | 2
}

export interface TableOfContentsProps {
  /**
   * One link per section, in the page's order.
   */
  items: TableOfContentsItem[]
  /**
   * The landmark's name, drawn above the list ("On this page").
   */
  label: string
  /**
   * Called with the current section's id, or `null`, each time it changes.
   */
  onCurrentChange?: (id: string | null) => void
}
</script>

<script lang="ts">
let { items, label: labelOwn, onCurrentChange }: TableOfContentsProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({ label: labelOwn }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
let current = $state(null as string | null)
let nav = $state<HTMLElement | null>(null)
const labelId = $derived(`${uid}-label`)
const groups = $derived(
  items.reduce(
    (groups, item, at) => {
      const parent = groups[groups.length - 1]
      if (item.level === 2 && parent !== undefined) parent.children.push({ item, at })
      else groups.push({ item, at, children: [] })
      return groups
    },
    [] as {
      item: TableOfContentsItem
      at: number
      children: { item: TableOfContentsItem; at: number }[]
    }[],
  ),
)
const currentAt = $derived(items.findIndex((item) => item.id === current))
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = watchSections(
    nav,
    items.map((item) => item.id),
    (id) => {
      if (id === current) return
      current = id
      onCurrentChange?.(id)
    },
  )
  release1 = () => {
    ran()
  }
}
watchEffect(effect1, { watch: () => items.map((item) => item.id).join(' ') })
onDestroy(() => release1?.())
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const ran = agentMember({
    member: 'TableOfContents',
    element: () => nav,
    state: () => ({
      current: current,
      items: items
        .filter((item, at) => items.findIndex((other) => other.id === item.id) === at)
        .map((item) => ({ id: item.id, label: item.label })),
    }),
    actions: {
      choose: {
        argument: 'id',
        run: (value) =>
          agentPress(nav?.querySelectorAll('a')[items.findIndex((item) => item.id === value)]),
      },
    },
  })
  release2 = () => {
    ran()
  }
}
watchEffect(effect2)
onDestroy(() => release2?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<nav bind:this={nav} class={styles.nav} aria-labelledby={labelId} data-member="table-of-contents"
    ><p class={styles.label} id={labelId}>{label}</p
    ><ul class={styles.list}
      >{#each groups as group (`${group.at}:${group.item.id}`)
        }<li class={styles.item}
          ><a
            class={styles.link}
            href={`#${group.item.id}`}
            aria-current={(group.at === currentAt) ? 'location' : undefined}
            onclick={(event) => { jumpToSection(nav, group.item.id, event) }}
            >{group.item.label
          }</a
          >{#if group.children.length > 0
            }<ul class={styles.sublist}
              >{#each group.children as child (`${child.at}:${child.item.id}`)
                }<li class={styles.item}
                  ><a
                    class={styles.link}
                    href={`#${child.item.id}`}
                    aria-current={(child.at === currentAt) ? 'location' : undefined}
                    onclick={(event) => { jumpToSection(nav, child.item.id, event) }}
                    >{child.item.label
                  }</a
                ></li
              >{/each
            }</ul
          >{/if
        }</li
      >{/each
    }</ul
  ></nav
>{/if
}{@render joined.end?.()}
